_ABBREV_TERMS = {
    'acei': 'ACE Inhibitor — blocks angiotensin-converting enzyme; used in HTN, HFrEF, CKD, post-MI; CI: pregnancy, bilateral renal artery stenosis; ADR: cough (bradykinin), angioedema',
    'ace inhibitor': 'ACE Inhibitor — blocks angiotensin-converting enzyme; used in HTN, HFrEF, CKD, post-MI; CI: pregnancy, bilateral renal artery stenosis; ADR: cough (bradykinin), angioedema',
    'arb': 'Angiotensin Receptor Blocker — blocks AT1 receptor; same indications as ACEi without cough/angioedema; ends in -sartan; CI: pregnancy',
    'ccb': 'Calcium Channel Blocker — dihydropyridines (amlodipine) = vasodilation; non-DHP (diltiazem/verapamil) = rate control + vasodilation; CI: non-DHP in HFrEF',
    'bb': 'Beta Blocker — β1 selective (metoprolol, atenolol) vs non-selective (carvedilol, propranolol); used in HTN, HF, arrhythmias, post-MI; CI: severe asthma, acute decompensated HF, heart block',
    'ssri': 'Selective Serotonin Reuptake Inhibitor — first-line for depression, anxiety, OCD, PTSD, panic disorder; ADR: sexual dysfunction, GI upset, serotonin syndrome (with MAOIs); takes 4–6 weeks for effect',
    'snri': 'Serotonin-Norepinephrine Reuptake Inhibitor — venlafaxine, duloxetine; depression, anxiety, neuropathic pain, fibromyalgia; ADR: HTN at high doses, discontinuation syndrome',
    'tca': 'Tricyclic Antidepressant — amitriptyline, nortriptyline, clomipramine; depression (2nd line), neuropathic pain, migraine prophylaxis; LETHAL in OD (QRS widening → arrhythmia); anticholinergic ADRs',
    'maoi': 'Monoamine Oxidase Inhibitor — phenelzine, tranylcypromine, selegiline; depression refractory to other agents; CI: tyramine-containing foods → hypertensive crisis; DDI: SSRIs → serotonin syndrome',
    'ppi': 'Proton Pump Inhibitor — omeprazole, pantoprazole, lansoprazole; irreversibly blocks H+/K+-ATPase; used for GERD, PUD, H. pylori (bismuth quadruple and other regimens), stress ulcer prophylaxis; ADR: C. diff, hypomagnesemia, B12 deficiency',
    'nsaid': 'Non-Steroidal Anti-Inflammatory Drug — COX-1/2 inhibitor (ibuprofen, naproxen) or COX-2 selective (celecoxib); analgesic, anti-inflammatory, antipyretic; ADR: GI ulcers, renal injury, platelet inhibition, HTN; CI: CKD, peptic ulcer disease',
    'dmard': 'Disease-Modifying Antirheumatic Drug — methotrexate (first-line RA), hydroxychloroquine, sulfasalazine, leflunomide; slows joint destruction in RA; monitor LFTs, CBC',
    'lmwh': 'Low Molecular Weight Heparin — enoxaparin, dalteparin; anti-Xa > anti-IIa activity; predictable dosing, no routine monitoring; used for DVT/PE treatment and prophylaxis; reversal: protamine (partial)',
    'doac': 'Direct Oral Anticoagulant — dabigatran (DTI), rivaroxaban/apixaban/edoxaban (anti-Xa); no routine monitoring; preferred over warfarin for non-valvular AF; reversal: idarucizumab (dabigatran), andexanet alfa (anti-Xa)',
    'statin': 'HMG-CoA Reductase Inhibitor — atorvastatin, rosuvastatin, simvastatin; ↓LDL 30–50%; used for primary/secondary prevention of ASCVD; ADR: myopathy/rhabdomyolysis (↑CK), hepatotoxicity (rare); CI: pregnancy',
    'dka': 'Diabetic Ketoacidosis — hyperglycemia (≥200 mg/dL — can be euglycemic on SGLT2 inhibitors) + anion gap metabolic acidosis + ketonemia/ketonuria; due to insulin deficiency (usually T1DM); tx: IV fluids, insulin drip, K+ replacement; complications: cerebral edema (children), hypokalemia',
    'hhs': 'Hyperosmolar Hyperglycemic State — extreme hyperglycemia (>600 mg/dL) + hyperosmolarity (>320 mOsm/kg) + no significant ketosis; usually T2DM elderly; high mortality; tx: aggressive IV fluids, insulin (after fluids), electrolytes',
    'ods': 'Osmotic Demyelination Syndrome — demyelination of pons (central pontine myelinolysis) ± extrapontine regions; caused by rapid correction of hyponatremia; presents: locked-in syndrome, dysarthria, dysphagia, quadriplegia; correct Na+ at ≤8 mEq/L per 24h',
    'cpm': 'Central Pontine Myelinolysis — see Osmotic Demyelination Syndrome (ODS); demyelination of pons from rapid hyponatremia correction; presents with locked-in syndrome, dysarthria, quadriplegia',
    'siadh': 'Syndrome of Inappropriate ADH — euvolemic hyponatremia; ↑ADH → ↑water retention → dilutional hyponatremia; causes: CNS disease, pulmonary disease, malignancy (SCLC), drugs (carbamazepine, SSRIs, cyclophosphamide); tx: fluid restriction, salt tabs, vaptans',
    'pcos': 'Polycystic Ovary Syndrome — hyperandrogenism + oligo/anovulation ± polycystic ovaries on US (Rotterdam criteria: 2 of 3); presents: irregular menses, hirsutism, acne, infertility; tx: OCPs (not trying to conceive), metformin, clomiphene (fertility)',
    'pe': "Pulmonary Embolism — thrombus in pulmonary vasculature; risk: Virchow's triad (stasis, hypercoagulability, endothelial injury); symptoms: pleuritic chest pain, dyspnea, hemoptysis, tachycardia; dx: CT-PA (gold standard); tx: anticoagulation, thrombolytics if massive",
    'dvt': 'Deep Vein Thrombosis — thrombus in deep veins (usually lower extremity); symptoms: unilateral leg swelling, pain, warmth, erythema; dx: compression US; tx: anticoagulation (LMWH/DOAC); provoked vs unprovoked determines duration',
    'svt': 'Supraventricular Tachycardia — narrow complex tachycardia originating above bundle of His; includes AVNRT (most common), AVRT, atrial flutter, AT; tx: vagal maneuvers → adenosine → CCB/BB; if unstable: cardioversion',
    'avnrt': 'AV Nodal Reentrant Tachycardia — most common SVT; reentry circuit in/around AV node; regular narrow complex tachycardia ~150-250 bpm; P waves hidden in or just after QRS; tx: vagal maneuvers, adenosine, CCB/BB',
    'wpw': 'Wolff-Parkinson-White Syndrome — accessory pathway (Bundle of Kent) bypassing AV node; ECG: short PR, delta wave, wide QRS; risk: rapid AF → VF; tx: ablation; AVOID adenosine/digoxin/CCB in AF',
    'avsd': 'Atrioventricular Septal Defect — endocardial cushion defect; common AV valve + ASD + VSD; strongly associated with Down syndrome; causes left-to-right shunt → pulmonary HTN',
    'hocm': 'Hypertrophic Obstructive Cardiomyopathy — asymmetric septal hypertrophy → LVOT obstruction; murmur ↑ with Valsalva/standing, ↓ with squat; MCC sudden cardiac death in young athletes; tx: BB or verapamil; AVOID inotropes, vasodilators',
    'af': 'Atrial Fibrillation — irregularly irregular rhythm; no distinct P waves; risk: HTN, valvular disease, HF, hyperthyroidism; rate control: BB/CCB; rhythm control: amiodarone/flecainide; anticoagulation: based on CHA₂DS₂-VASc score',
    'vt': 'Ventricular Tachycardia — wide complex tachycardia (QRS >120ms) at rate >100; monomorphic vs polymorphic (torsades); if hemodynamically unstable: synchronized cardioversion; stable: amiodarone/lidocaine; sustained VT needs ICD evaluation',
    'vf': 'Ventricular Fibrillation — chaotic ventricular rhythm; no cardiac output → cardiac arrest; tx: immediate defibrillation (unsynchronized shock) + CPR; most common initial rhythm in witnessed cardiac arrest',
    'chf': 'Congestive Heart Failure — see Heart Failure; systolic (HFrEF, EF<40%) vs diastolic (HFpEF, EF≥50%); symptoms: dyspnea, orthopnea, PND, edema; tx HFrEF: ACEi/ARB/ARNI + BB + MRA + SGLT2i',
    'hfref': 'Heart Failure with Reduced Ejection Fraction — EF <40%; neurohormonal activation (RAAS, SNS); tx: ACEi/ARB/sacubitril-valsartan + carvedilol/metoprolol + spironolactone + SGLT2i; avoid CCBs (non-DHP)',
    'hfpef': 'Heart Failure with Preserved Ejection Fraction — EF ≥50%; diastolic dysfunction; risk factors: HTN, DM, obesity, older women; tx: diuretics (symptom relief), SGLT2i; treat underlying HTN/AF',
    'ards': 'Acute Respiratory Distress Syndrome — bilateral infiltrates + PaO₂/FiO₂ <300 + no cardiac cause; causes: pneumonia, sepsis, aspiration, trauma; tx: low tidal volume ventilation (6 mL/kg IBW), PEEP, prone positioning if severe',
    'copd': 'Chronic Obstructive Pulmonary Disease — emphysema + chronic bronchitis; caused by smoking; FEV1/FVC <0.70; tx: SABA (rescue), LAMA + LABA (maintenance), add ICS if exacerbations and blood eosinophils ≥300; acute exacerbation: bronchodilators, steroids, antibiotics',
    'gerd': "Gastroesophageal Reflux Disease — retrograde flow of gastric contents; symptoms: heartburn, regurgitation, dysphagia; complications: Barrett's esophagus → adenocarcinoma; dx: clinical; tx: lifestyle mods, PPIs; endoscopy if alarm symptoms",
    'ibd': "Inflammatory Bowel Disease — Crohn's disease vs ulcerative colitis; chronic relapsing-remitting GI inflammation; Crohn: skip lesions, transmural, any GI segment, can fistulize; UC: continuous, mucosal, colon only, rectal sparing rare",
    'uc': 'Ulcerative Colitis — continuous mucosal inflammation of colon starting at rectum; bloody diarrhea, tenesmus; extraintestinal: pyoderma gangrenosum, primary sclerosing cholangitis (PSC strongly associated); tx: 5-ASA (mild), steroids (moderate), biologics (severe)',
    'cd': "Crohn's Disease — transmural granulomatous inflammation, any GI segment (mouth to anus), skip lesions, cobblestoning, fistulas, strictures; extraintestinal: erythema nodosum, uveitis, ankylosing spondylitis; tx: steroids, immunomodulators, anti-TNF",
    'ibs': 'Irritable Bowel Syndrome — functional GI disorder; altered bowel habits + abdominal pain relieved by defecation; no structural abnormality; Rome IV criteria: recurrent abdominal pain ≥1 day/week for ≥3 months; subtypes: IBS-C, IBS-D, IBS-M',
    'pud': 'Peptic Ulcer Disease — mucosal break >5mm in stomach or duodenum; causes: H. pylori (MCC), NSAIDs, Zollinger-Ellison; duodenal (1st part): worse with hunger, relieved by food; gastric: worsened by food; dx: endoscopy; tx: PPI + H. pylori eradication if present',
    'aki': 'Acute Kidney Injury — ↑Cr ≥0.3 mg/dL in 48h OR ↑Cr ≥1.5× baseline in 7 days OR UO <0.5 mL/kg/h for 6h; prerenal (most common) vs intrinsic (ATN, GN) vs postrenal; prerenal: BUN/Cr >20, FeNa <1%; ATN: muddy brown casts, FeNa >2%',
    'ckd': 'Chronic Kidney Disease — GFR <60 for >3 months OR kidney damage markers; stages G1-G5 by GFR + A1-A3 by albuminuria; causes: DM (MCC), HTN, GN; complications: anemia (↓EPO), hyperPTH, metabolic acidosis, hyperkalemia, uremia; tx: treat underlying cause, ACEi/ARB',
    'esrd': 'End-Stage Renal Disease — GFR <15 (CKD G5); requires dialysis (HD/PD) or transplant; complications: uremic pericarditis, encephalopathy, platelet dysfunction, pruritus',
    'uti': 'Urinary Tract Infection — cystitis (lower): dysuria, frequency, urgency, suprapubic pain; pyelonephritis (upper): fever, flank pain, CVA tenderness + lower UTI symptoms; dx: UA + culture; tx: nitrofurantoin/TMP-SMX (cystitis); fluoroquinolone/cephalosporin (pyelo)',
    'ms': 'Multiple Sclerosis — CNS demyelinating disease; relapsing-remitting (85%) most common; lesions disseminated in time and space; symptoms: optic neuritis, INO (MLF lesion), Lhermitte sign, spasticity, bladder dysfunction; dx: MRI (periventricular plaques), CSF oligoclonal bands',
    'als': 'Amyotrophic Lateral Sclerosis — UMN + LMN degeneration; UMN: spasticity, hyperreflexia, Babinski; LMN: weakness, atrophy, fasciculations; bulbar onset: dysarthria, dysphagia (worse prognosis); tx: riluzole (modest benefit), edaravone; median survival 3-5 years',
    'tia': 'Transient Ischemic Attack — focal neurological deficit lasting <24h (usually <1h) with no infarction on MRI; high risk of subsequent stroke (ABCD² score); tx: antiplatelet therapy, carotid US, cardiac monitoring, risk factor management',
    'cva': 'Cerebrovascular Accident (Stroke) — ischemic (85%) vs hemorrhagic (15%); ischemic tx: tPA if <4.5h (no CI) + thrombectomy if large vessel occlusion; hemorrhagic: reverse anticoagulation, BP control, neurosurgical evaluation; time is brain',
    'osa': 'Obstructive Sleep Apnea — repetitive upper airway collapse during sleep; symptoms: snoring, witnessed apneas, daytime somnolence; risk: obesity, male sex, large neck circumference; dx: polysomnography (AHI ≥5); tx: CPAP (first-line), weight loss',
    'ra': 'Rheumatoid Arthritis — symmetric polyarthritis of small joints (MCPs, PIPs — spares DIPs); morning stiffness >1h; RF/anti-CCP positive; extra-articular: rheumatoid nodules, ILD, pericarditis, scleritis; tx: MTX (first-line DMARD), add biologics if inadequate response',
    'sle': 'Systemic Lupus Erythematosus — multisystem autoimmune; ANA (sensitive), anti-dsDNA + anti-Smith (specific); SOAP BRAIN MD mnemonic; drug-induced SLE: anti-histone Abs; lupus nephritis (class III/IV): cyclophosphamide or mycophenolate',
    'dm': 'Dermatomyositis — inflammatory myopathy + skin findings; heliotrope rash, Gottron papules, V-sign, shawl sign; ↑CK, ↑aldolase; EMG: myopathic pattern; paraneoplastic (screen for malignancy); tx: steroids + steroid-sparing agent',
    'gbs': 'Guillain-Barré Syndrome — ascending symmetric flaccid paralysis + areflexia after GI/respiratory infection (Campylobacter, CMV, EBV); CSF: albuminocytologic dissociation (↑protein, normal WBC); tx: IVIg or plasmapheresis; monitor respiratory function',
    'mg': 'Myasthenia Gravis — autoimmune NMJ disorder; anti-AChR Ab (85%) or anti-MuSK Ab; weakness worsens with use; ptosis, diplopia, dysphagia, respiratory failure; dx: anti-AChR/MuSK antibodies, repetitive nerve stimulation, single-fiber EMG (edrophonium test no longer available in the US); tx: pyridostigmine, immunosuppression, thymectomy',
    'hiv': 'Human Immunodeficiency Virus — retrovirus attacking CD4+ T cells; CD4 <200 = AIDS; opportunistic infections: PCP (CD4 <200), toxoplasmosis (CD4 <100), CMV retinitis (CD4 <50), MAC (CD4 <50); tx: ART (2 NRTIs + INSTI preferred)',
    'tb': 'Tuberculosis — Mycobacterium tuberculosis; primary (often asymptomatic, Ghon complex) vs reactivation (upper lobe cavitation); RIPE therapy: Rifampin, Isoniazid, Pyrazinamide, Ethambutol × 2 months then RI × 4 months; INH ADR: hepatitis, peripheral neuropathy (give B6)',
    'gfr': 'Glomerular Filtration Rate — estimate of kidney filtration capacity; normal >90 mL/min/1.73m²; estimated with the race-free CKD-EPI 2021 equation (creatinine ± cystatin C, age, sex); <60 for >3 months = CKD; <15 = ESRD requiring RRT',
    'egfr': 'Estimated Glomerular Filtration Rate — calculated using CKD-EPI equation from serum creatinine, age, sex; normal >90 mL/min/1.73m²; better reflects true GFR than raw creatinine; used to stage CKD and adjust drug dosing',
    'bun': 'Blood Urea Nitrogen — waste product of protein metabolism; normal 7-20 mg/dL; elevated in AKI/CKD, prerenal states, GI bleed, high protein intake; BUN/Cr ratio >20 suggests prerenal or GI bleed',
    'cbc': 'Complete Blood Count — WBC (4.5-11K), RBC, Hgb, Hct, MCV, MCHC, platelets, differential; key for diagnosing anemia, infection, thrombocytopenia, leukemia',
    'bmp': 'Basic Metabolic Panel — Na, K, Cl, HCO3, BUN, Cr, glucose, Ca; evaluates electrolytes, acid-base status, kidney function, glucose',
    'cmp': 'Comprehensive Metabolic Panel — BMP + LFTs (AST, ALT, ALP, bilirubin, albumin, total protein); evaluates metabolic status + liver function',
    'lft': 'Liver Function Tests — AST, ALT, ALP, GGT, total/direct bilirubin, albumin, total protein, PT/INR; hepatocellular pattern: ↑↑AST/ALT; cholestatic: ↑↑ALP/GGT/bilirubin',
    'inr': 'International Normalized Ratio — standardized measure of PT; normal ~1.0; therapeutic range for warfarin: 2-3 (AF, DVT/PE) or 2.5-3.5 (mechanical heart valve); elevated in liver disease, warfarin use, vitamin K deficiency, DIC',
    'abg': 'Arterial Blood Gas — pH (7.35-7.45), PaCO₂ (35-45 mmHg), PaO₂ (80-100 mmHg), HCO₃ (22-26 mEq/L); use to assess acid-base disorders and oxygenation; step-by-step: acidosis vs alkalosis → respiratory vs metabolic → compensation → anion gap',
    'vbg': 'Venous Blood Gas — pH ~0.04 lower, pCO₂ ~6 mmHg higher than ABG; useful to assess acid-base status when arterial access difficult; pO₂ not reliable for oxygenation assessment',
    'bnp': 'B-type Natriuretic Peptide — released by ventricular myocytes in response to ↑wall stress; elevated in HF (>100 pg/mL suggests HF); used to diagnose and monitor HF; also elevated in PE, renal failure, sepsis',
    'ck': 'Creatine Kinase — enzyme in muscle, heart, brain; CK-MM (skeletal muscle), CK-MB (cardiac), CK-BB (brain); total CK elevated in rhabdomyolysis, myocarditis, myopathy; CK-MB elevated in MI (peaks 24h, normalizes 48-72h)',
    'trop': 'Troponin — cardiac-specific protein (cTnI, cTnT); elevated within 2-4h of MI, peaks 24-48h, persists up to 2 weeks (cTnI) or longer; high-sensitivity troponin allows rapid rule-in/rule-out (0/1h or 0/2h protocols); also elevated in PE, myocarditis, sepsis, renal failure',
    'tsh': 'Thyroid-Stimulating Hormone — secreted by anterior pituitary; ↑TSH = hypothyroidism (primary); ↓TSH = hyperthyroidism or pituitary/hypothalamic disease; most sensitive test for thyroid dysfunction; check with free T4',
    'hba1c': 'Hemoglobin A1c — reflects average blood glucose over ~3 months; normal <5.7%; pre-diabetes 5.7-6.4%; DM diagnosis ≥6.5%; ADA target for most diabetics <7%; not reliable in hemolytic anemia, hemoglobinopathies',
    'ldl': 'Low-Density Lipoprotein — primary atherogenic lipoprotein; target depends on ASCVD risk; very high risk (<55 mg/dL), high risk (<70 mg/dL), moderate risk (<100 mg/dL); calculated via Friedewald equation or directly measured',
    'hdl': 'High-Density Lipoprotein — reverse cholesterol transport; protective against ASCVD; low HDL (<40 mg/dL men, <50 mg/dL women) is independent risk factor; ↑by exercise, niacin, fibrates; ↓by smoking, DM, obesity, sedentary lifestyle',
    'psa': 'Prostate-Specific Antigen — serine protease produced by prostate; used for prostate cancer screening (controversial); normal <4 ng/mL (age-adjusted); elevated in BPH, prostatitis, prostate cancer; PSA velocity and free PSA help differentiate',
    'cea': 'Carcinoembryonic Antigen — tumor marker; elevated in colorectal cancer (MCC), gastric, lung, breast cancer, heavy smoking; used for monitoring response to treatment and detecting recurrence; NOT used for screening',
    'afp': 'Alpha-Fetoprotein — fetal protein; elevated in HCC (>400 ng/mL highly suggestive), hepatoblastoma, testicular/ovarian germ cell tumors, neural tube defects (maternal serum); used for HCC surveillance in cirrhosis',
    'ca125': 'CA-125 — glycoprotein elevated in epithelial ovarian cancer (serous); also elevated in endometriosis, PID, pregnancy, liver disease; not specific enough for screening; used for monitoring treatment response and recurrence',
    'ecg': 'Electrocardiogram — 12-lead recording of cardiac electrical activity; assess rate, rhythm, axis, intervals (PR, QRS, QTc), ST changes, hypertrophy, conduction defects; leads II, III, aVF = inferior; I, aVL, V5, V6 = lateral; V1-V4 = anterior',
    'ekg': 'Electrocardiogram — see ECG; 12-lead recording of cardiac electrical activity; standard paper speed 25 mm/s; 1 small box = 0.04s; 1 large box = 0.2s; rate = 300 ÷ number of large boxes between R waves',
    'echo': 'Echocardiogram — cardiac ultrasound; assesses EF, wall motion, valvular function, pericardial effusion, wall thickness; TTE (transthoracic) vs TEE (transesophageal — better for endocarditis, aortic dissection, LA thrombus)',
    'cath': 'Cardiac Catheterization — invasive coronary angiography; gold standard for CAD diagnosis; right heart cath: hemodynamic assessment (PCWP, CO, PA pressures); left heart cath: coronary anatomy + LV function; PCI can be performed simultaneously',
    'pci': 'Percutaneous Coronary Intervention — balloon angioplasty ± stent placement; primary PCI preferred over thrombolytics in STEMI if door-to-balloon <90 min; DES (drug-eluting stent) preferred; dual antiplatelet therapy required post-stent',
    'cabg': 'Coronary Artery Bypass Grafting — surgical revascularization; preferred over PCI in: left main disease, 3-vessel CAD with reduced EF, DM with multivessel CAD; LIMA-to-LAD graft = gold standard (>90% patency at 10 years)',
    'ercp': 'Endoscopic Retrograde Cholangiopancreatography — combined endoscopy + fluoroscopy to visualize biliary + pancreatic ducts; therapeutic (stone extraction, stent placement) and diagnostic; complication: pancreatitis (MCC), bleeding, perforation, cholangitis',
    'eus': 'Endoscopic Ultrasound — combines endoscopy with high-frequency ultrasound; evaluates submucosal lesions, pancreatic masses, lymph nodes, bile duct; fine needle aspiration (FNA) guided by EUS for tissue diagnosis',
    'ct': 'Computed Tomography — X-ray based cross-sectional imaging; CT chest/abdomen/pelvis with contrast most common in ER; non-contrast CT head first for stroke/trauma; CT-PA for PE; HU (Hounsfield units): air=-1000, fat=-100, water=0, blood=+50, bone=+400',
    'mri': 'Magnetic Resonance Imaging — no radiation; better soft tissue contrast than CT; T1 (fat bright, fluid dark), T2 (fluid bright); DWI for acute stroke; MRI with gadolinium for CNS/soft tissue lesions; CI: pacemaker, certain metal implants',
    'lp': 'Lumbar Puncture — CSF analysis; normal: clear, pressure 10-20 cm H₂O, WBC <5, protein 15-45, glucose 50-75 mg/dL (>2/3 serum glucose); xanthochromia in SAH; opening pressure ↑in meningitis, IIH; send for cell count, protein, glucose, culture, gram stain',
    'eeg': 'Electroencephalogram — records cortical electrical activity; used for seizure diagnosis/monitoring, encephalopathy (triphasic waves), brain death (isoelectric); spike-and-wave pattern in epilepsy; FIRDA in encephalopathy',
    'emg': 'Electromyography — assesses muscle electrical activity; myopathic pattern: small, short, polyphasic MUAPs; neuropathic: large, long MUAPs + fibrillations; combined with nerve conduction studies (NCS) to localize neuromuscular disease',
    'abi': 'Ankle-Brachial Index — ratio of ankle to brachial systolic BP; normal 1.0-1.4; 0.91-0.99 borderline; ≤0.9 = PAD; >1.4 = non-compressible vessels (calcified, as in DM); claudication typical with ABI 0.4-0.9; critical limb ischemia <0.4',
    'bp': 'Blood Pressure — systolic (ventricular contraction) / diastolic (ventricular relaxation) in mmHg; normal <120/80; stage 1 HTN 130-139/80-89; stage 2 HTN ≥140/90; hypertensive urgency ≥180/120 without end-organ damage; emergency: with end-organ damage',
    'hr': 'Heart Rate — beats per minute; normal 60-100 bpm; bradycardia <60 (causes: BB, CCB, hypothyroidism, athletic training, high vagal tone); tachycardia >100 (causes: fever, pain, hypovolemia, hyperthyroidism, PE, anemia)',
    'rr': 'Respiratory Rate — breaths per minute; normal 12-20; tachypnea >20 (fever, acidosis, PE, pneumonia, anxiety); bradypnea <12 (opioids, sedation, brainstem lesion); early sign of clinical deterioration (often first vital sign to change)',
    'spo2': 'Oxygen Saturation (Pulse Oximetry) — SpO₂ normal ≥95%; below 90% = significant hypoxemia; falsely normal in CO poisoning (reads HbCO as oxygenated); plateaus ~85% in methemoglobinemia; affected by poor perfusion and nail polish; overestimates saturation in darker skin (occult hypoxemia)',
    'map': 'Mean Arterial Pressure — average arterial pressure during cardiac cycle; MAP = DBP + 1/3 (SBP - DBP) ≈ (SBP + 2×DBP)/3; normal 70-100 mmHg; MAP <65 = shock/hypoperfusion; target >65 mmHg in septic shock',
    'jvp': 'Jugular Venous Pressure — reflects right atrial pressure; measured in cm H₂O from sternal angle; normal <4 cm (≤8 cm from RA); elevated in RHF, cardiac tamponade, constrictive pericarditis, SVC obstruction; Kussmaul sign: ↑JVP with inspiration (constrictive pericarditis)',
    'cvp': 'Central Venous Pressure — right atrial pressure measured via central line; normal 2-8 mmHg; ↓in hypovolemia; ↑in RHF, cardiac tamponade, fluid overload; poor predictor of fluid responsiveness',
}
